import os

def factorial(n, mod):
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod
    return result

def power(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp //= 2
        base = (base * base) % mod
    return result

def inverse(n, mod):
    return power(n, mod - 2, mod)

def nCr(n, r, mod):
    if r < 0 or r > n:
        return 0
    num = factorial(n, mod)
    den = (factorial(r, mod) * factorial(n - r, mod)) % mod
    return (num * inverse(den, mod)) % mod

