        """Check if a is a geometric progression"""
        if len(a) <= 2:
            return True
        if all(x == 0 for x in a):
            return True

        # Count non-zero elements
        nonzero_count = sum(1 for x in a if x != 0)

        if nonzero_count <= 1:
            return True

        # Find the ratio from first two non-zero elements
        first_nonzero_idx = -1
        second_nonzero_idx = -1
        ratio = None

        for i, x in enumerate(a):
