                if first_nonzero_idx == -1:
                    first_nonzero_idx = i
                    second_nonzero_idx = None
                elif second_nonzero_idx == None:
                    second_nonzero_idx = i
                    break

        # Calculate ratio from consecutive non-zero elements
        for i in range(1, len(a)):
            if a[i-1] != 0 and a[i] != 0 and ratio is None:
                ratio = a[i] / abs(a[i-1])
            if ratio is not None:
                # Use multiplication to avoid precision issues
                if a[i-1] * ratio != a[i]:
                    # Allow small tolerance for floating point
