    MAX_LOG = 20
    up = [[0] * MAX_LOG for _ in range(n + 1)]
    mx = [[0] * MAX_LOG for _ in range(n + 1)]

    for v in range(1, n + 1):
        up[v][0] = parent_list[v]
        mx[v][0] = weight_to_parent[v]

    for j in range(1, MAX_LOG):
        for i in range(1, n + 1):
            if up[i][j - 1] != 0:
                up[i][j] = up[up[i][j - 1]][j - 1]
                mx[i][j] = max(mx[i][j - 1], mx[up[i][j - 1]][j - 1])

    # LCA function
