import sys

def get_prime_factors(n):
    """Get prime factors of n"""
    factors = set()
    if n <= 0:
        return factors
    d = 2
    while d * d <= abs(n):
        while abs(n) % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if abs(n) > 1:
        factors.add(abs(n))
    return factors

