    # Edge case: n=1, cannot remove entire array, element already >= 2
    if n == 1:
        return "0\n"

    # Collect candidate G values from prime factors of nearby numbers
    candidates = set()
    candidates.add(2)  # Always try 2

    # Sample elements to collect candidates (limit to prevent too many)
    sample_size = min(200, n)
    for i in range(sample_size):
        for offsetX in [-1, 0, 1]:
            val = arr[i] + offsetX
            for p in get_prime_factors(val):
                if p > 1:
                    candidates.add(p)

    # Limit candidates to reasonable size
    if len(candidates) > 1000:
        candidates = list(candidates)[:1000]

    min_cost = float('inf')

    for g in candidates:
        if g <= 1:
            continue

        # Step 1: Calculate base cost without removal
        base_cost = 0
        valid = True

        for x in arr:
            if x % g != 0:
                # Check if can change by 0 or 1 to make divisible by g
                if (x - 1) % g == 0 or (x + 1) % g == 0:
                    base_cost += b
                else:
                    valid = False
                    break

        if not valid:
            continue

        # Update min_cost with no removal case
        min_cost = min(min_cost, base_cost)

        # Step 2: Find best segment to remove
        # For each position, compute benefit of removal:
        # - If needs change: benefit is (b - a) [save change cost, pay removal cost]
        # - If doesn't need change: benefit is -a [just pay removal cost]

        benefits = []
        for x in arr:
            if x % g != 0:
                benefits.append(b - a)
            else:
                benefits.append(-a)

        # Maximum subarray sum (Kadane's) - can't remove entire array
        # We can leave 1 element, so removal segment can be [0, n-2] or [1, n-1]
        max_benefit = 0
        current = 0

        for i in range(n):  # Include all, but ensure we don't remove everything
            current += benefits[i]
            if current > max_benefit:
                max_benefit = current

            if current < 0:
                current = 0

        # Try removing segment that ends before last element OR starts after first
        # Ensure at least one element remains
        # Maximum segment that can be removed is n-1 elements

        max_benefit = 0
        current = 0
        for i in range(n - 1):  # First n-1 elements (leaving at least last one)
            current += benefits[i]
            if current > max_benefit:
                max_benefit = current
            if current < 0:
                current = 0

        if max_benefit > 0:
            min_cost = min(min_cost, base_cost - max_benefit)

    # Final fallback if g=2 was valid (should always work)
    if min_cost == float('inf'):
        min_cost = 0  # Shouldn't happen given problem constraints

    return f"{min_cost}\n"

