def is_bitonic(arr):
    """Check if array is bitonic: increases to a peak, then decreases."""
    n = len(arr)
    if n <= 1:
        return True
    if n == 2:
        return True  # Single comparison, always bitonic-like

    # Find the peak position (increases up to it, decreases after)
    peak = -1
    for i in range(1, n - 1):
        if arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
            peak = i
            break

    if peak == -1:
        # No interior peak - must be monotonic
        non_decreasing = all(arr[i] <= arr[i + 1] for i in range(n - 1))
        non_increasing = all(arr[i] >= arr[i + 1] for i in range(n - 1))
        return non_decreasing or non_increasing

    # Verify it increases up to peak, then decreases
    for i in range(1, peak):
        if arr[i] <= arr[i - 1]:
            return False
    for i in range(peak + 1, n):
        if arr[i] >= arr[i - 1]:
            return False
    return True


