def get_prime_factors(n):
    """Get all distinct prime factors of n"""
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def get_gcd_of_list(nums):
    """Get GCD of a list of numbers"""
    result = nums[0]
    for x in nums[1:]:
        result = math.gcd(result, x)
    return result

