    # For each prime factor, find the minimum experience among judges who can eliminate it
    # A judge i can eliminate prime p if a[i] is divisible by some multiple of p that is <= k
    # We find min experience where p divides (a[i] / d) for some d <= k, which means
    # a[i] must be divisible by p

    min_exp_for_each_p = []
    for p in prime_factors:
        min_e_for_p = float('inf')
        for i in range(n):
            if a[i] % p == 0:
                min_e_for_p = min(min_e_for_p, e[i])
        min_exp_for_each_p.append(min_e_for_p)

    # Try all possible subset sizes and combinations to find minimum cost
    prime_factor_list = list(prime_factors)
    best_cost = float('inf')

    # Try playing with different numbers of judges
    for num_judges_to_play in range(1, len(prime_factors) + 1):
        for subset in combinations(prime_factor_list, num_judges_to_play):
            total_exp = 0
            for p in subset:
                for i in range(n):
                    if a[i] % p == 0:
                        total_exp += e[i]
                        break  # Pick minimum experience for this prime (first valid)
                else:
                    continue  # No judge can eliminate this prime
                break  # Moving to next prime in subset
            else:
                continue  # No valid judges for all primes in subset
                # Actually, if we got here without break/continue, means subset worked
